// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airDrop} from "../src/airDrop.sol";

contract DummyToken {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
    function transfer(address, uint256) external pure returns (bool) {
        revert("transfer not supported");
    }
}

contract InvMutTest is Test {
    airDrop c;
    DummyToken token;
    address from = address(0x1234);
    address to = address(0x5678);

    function setUp() public {
        c = new airDrop();
        token = new DummyToken();
    }

    function testRegression_property() public {
        address[] memory recipients = new address[](1);
        recipients[0] = to;

        bool ok;
        try c.transfer(from, address(token), recipients, 1, 1) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok, "Reference should succeed, buggy reverts");
    }
}
